export function forumCopy(locale) {
  const row = rows[locale];
  const lengths = [keys.length, 4, 2, 5];
  if (!row || row.length !== lengths.length || row.some((part, i) => !Array.isArray(part) || part.length !== lengths[i] || part.some((s) => typeof s !== "string" || !s.trim()))) {
    throw new Error(`Missing or incomplete forum translation: ${locale}`);
  }
  const map = (names, values) => Object.fromEntries(names.map((name, i) => [name, values[i]]));
  return {
    ...map(keys, row[0]),
    interests: map(["products", "infrastructure", "education", "partnerships"], row[1]),
    hostingOptions: map(["host", "coorganise"], row[2]),
    statuses: map(["submitted", "under_review", "invited", "attendance_confirmed", "withdrawn"], row[3])
  };
}
